import{z as s,x as l,o as t,c as d,q as r,j as A,D as B,d as e,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"生育的经济学","description":"","frontmatter":{"title":"生育的经济学","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fertility-econ.md","filePath":"econ/fertility-econ.md","lastUpdated":1791063341000}'),p={name:"econ/fertility-econ.md"};function D(c,E,C,m,h,u){const n=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="生育的经济学" tabindex="-1">生育的经济学 <a class="header-anchor" href="#生育的经济学" aria-label="Permalink to &quot;生育的经济学&quot;">​</a></h1><div class="epigraph"><p>孩子是耐用品还是投资品？收入涨了生育反降——贝克尔的质量-数量替代是人口经济学那把万能钥匙。</p><footer>—— 据 Becker「A Treatise on the Family」(1981)；Becker–Lewis 数量-质量模型 (1973)</footer></div><p><a href="/econ/insider-outsider-labor">内部人-外部人模型</a>解释年轻人为何难进职场，本课接着问：难进职场之后为何也难成家生子。缺口是<strong>生育的微观经济学</strong>——把「生几个、投多少」写成父母的效用最大化问题。本课不进宏观人口增长的跨代模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典谜题：马尔萨斯预言收入升则人口升，现代数据却是收入越高的国家生育率越低（收入弹性为负）。缺口在于孩子的「价格」与「质量」都随发展变化——把「多生」与「养好」拆开，负相关迎刃而解。要回答：数量-质量替代如何生成，女性工资在里面扮演什么角色。</p><p><span class="marginnote">术语翻译：数量-质量替代（quantity-quality trade-off）= 孩子个数与每个孩子的投入（教育、健康）在家庭预算里此消彼长；孩子的影子价格 = 养育占用的时间按母亲工资计价的机会成本。</span></p><p><span class="marginnote">数字实例：养育到 18 岁需母亲 5 年主要照护时间。母亲时薪 30 元时孩子影子价格约 26 万元；时薪涨到 100 元则约 87 万元——价格涨到三倍多，生育意愿自然下行。而「质量」侧的教育投入从补课到留学几乎无上限，预算约束掐住数量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Becker–Lewis 模型三要素：预算约束 \\(p_n n + p_q q n + c = Y\\)（数量 \\(n\\)、每孩质量 \\(q\\)、其他消费 \\(c\\)）；效用 \\(U(n, q, c)\\)；关键在 \\(p_q q n\\) 这一交叉项——质量投入随数量<strong>成倍放大</strong>。推论：收入升时若质量弹性大于数量弹性，家庭用「少生优育」替代「多生」；女性工资上升抬高数量价格，数量再降。</p>',9)),(t(),A(i,null,{default:B(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%B6%E5%BA%AD%E9%A2%84%E7%AE%97%20Y%22%5D%20--%3E%20B%5B%22%E5%AD%A9%E5%AD%90%E6%95%B0%E9%87%8F%20n%20%C3%97%20%E5%8D%95%E5%AD%A9%E4%BB%B7%E6%A0%BC%20p%22%5D%0A%20%20A%20--%3E%20C%5B%22%E8%B4%A8%E9%87%8F%E6%8A%95%E5%85%A5%20q%20%C3%97%20n%20(%E4%BA%A4%E5%8F%89%E9%A1%B9!)%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%85%B6%E4%BB%96%E6%B6%88%E8%B4%B9%20c%22%5D%0A%20%20B%20--%3E%20E%7B%22%E6%94%B6%E5%85%A5%E4%B8%8A%E5%8D%87%22%7D%0A%20%20C%20--%3E%20E%0A%20%20E%20--%3E%7C%22%E8%B4%A8%E9%87%8F%E5%BC%B9%E6%80%A7%20%3E%20%E6%95%B0%E9%87%8F%E5%BC%B9%E6%80%A7%22%7C%20F%5B%22%E5%B0%91%E7%94%9F%20%2B%20%E6%AF%8F%E5%AD%A9%E9%87%8D%E6%8A%95%E5%85%A5%22%5D%0A%20%20E%20--%3E%7C%22%E5%A5%B3%E6%80%A7%E5%B7%A5%E8%B5%84%E2%86%91%22%7C%20G%5B%22%E6%95%B0%E9%87%8F%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%E2%86%91%22%5D%0A%20%20F%20--%3E%20H%5B%22%E7%94%9F%E8%82%B2%E7%8E%87%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20G%20--%3E%20H%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：预算固定时的「买手机」选择——价格涨十倍（女性工资升），你会从「买三部」改为「买一部旗舰」；孩子从「劳动力的数量储备」变成「全家的旗舰项目」，正是历史上从农场经济到城市经济的切换。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("两条机制接住历史事实。"),a("strong",null,"价格机制"),e("：农业社会孩子 7 岁即产工，数量便宜；城市中教育年限拉长，孩子从投资品变成耐用品，数量需求崩塌。"),a("strong",null,"机会成本机制"),e("：生育率对女性工资的弹性显著大于对男性工资——生儿育女的时间主要落在母亲头上，母亲工资是数量的价格、父亲工资只是收入。政策含义分化：现金补贴抬高收入（效应弱）、托育服务压低时间价格（效应强）、教育军备竞赛推高质量价格（反向效应，东亚低生育率陷阱的候选解释）。")],-1)),(t(),A(i,null,{default:B(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%E6%AF%8D%E4%BA%B2%E5%B7%A5%E8%B5%84%E5%BC%B9%E6%80%A7%E6%9C%80%E5%A4%A7%3F%22%7D%20--%3E%20R%5B%22%E7%85%A7%E6%8A%A4%E6%97%B6%E9%97%B4%E4%B8%BB%E8%A6%81%E8%90%BD%E5%9C%A8%E6%AF%8D%E4%BA%B2%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%AF%8D%E4%BA%B2%E5%B7%A5%E8%B5%84%20%3D%20%E6%95%B0%E9%87%8F%E7%9A%84%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20S%20--%3E%20T%5B%22%E6%B6%A8%2010%25%20%E2%86%92%20%E7%94%9F%E8%82%B2%E7%8E%87%E9%99%8D%E6%98%BE%E8%91%97%22%5D%0A%20%20U%7B%22%E6%94%BF%E7%AD%96%E5%93%AA%E5%AE%B6%E5%BC%BA%3F%22%7D%20--%3E%7C%22%E7%8E%B0%E9%87%91%E8%A1%A5%E8%B4%B4%22%7C%20V%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%BC%B1%22%5D%0A%20%20U%20--%3E%7C%22%E6%89%98%E8%82%B2%E6%9C%8D%E5%8A%A1%22%7C%20W%5B%22%E6%97%B6%E9%97%B4%E4%BB%B7%E6%A0%BC%E2%86%93%2C%20%E6%95%88%E5%BA%94%E5%BC%BA%22%5D%0A%20%20U%20--%3E%7C%22%E6%95%99%E8%82%B2%E7%AB%9E%E8%B5%9B%22%7C%20X%5B%22%E8%B4%A8%E9%87%8F%E4%BB%B7%E6%A0%BC%E2%86%91%2C%20%E5%8F%8D%E5%90%91%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：用「文化偏好不变」解释生育率差异——同源族群跨国比较显示收入与托育政策解释了大部分方差；另一误区是把低生育率归因于「补贴不够多」，忽视了影子价格机制里「时间」比「钱」更贵。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型假设父母自主决策， ignores 制度约束（计划生育、移民政策）与不确定性与婚姻市场匹配；质量-数量替代在死亡率高的社会失灵（需多生对冲夭折）。数据上生育意愿与实际生育的缺口（南欧、东亚「生育gap」）指向制度而非偏好。与<a href="/econ/household-production">家庭生产</a>共享时间套利地基，与<a href="/econ/insider-outsider-labor">内部人-外部人</a>拼成「就业不稳 → 成家推迟 → 生育下降」的传导链。</p><p><span class="marginnote">直觉类比：孩子像一辆养起来越来越贵的车——工资涨了，买车位（住房）、考驾照（教育）都变贵，你会从「家里三辆车」换成「一辆好车」；补课费就是那笔没有上限的「改装预算」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数量-质量替代：质量投入乘数量放大，收入升 → 少生优育。</li><li>母亲工资是孩子数量的价格，其弹性远大于父亲工资。</li><li>政策排序：压时间价格（托育）&gt; 现金补贴 &gt; 无作为；教育竞赛反向。</li><li>出处：Becker–Lewis 1973；《A Treatise on the Family》1981；Doepke 2004 综述。</li></ul>',6))])}const F=s(p,[["render",D]]);export{_ as __pageData,F as default};
